import {accessStatus,requestAccess,decideAccess,accessPayload,validatePass} from './access.mjs';

const escape = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>new Date(value).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const labels={profile:'Заполните профиль для получения доступа',unpaid:'Подтвердите тестовую оплату',new:'Профиль ещё не отправлен владельцу',changed:'Профиль изменён: нужно новое подтверждение',pending:'Профиль на подтверждении у владельца',rejected:'Владелец отклонил заявку',revoked:'Доступ отозван владельцем',ready:'Профиль подтверждён. QR-код готов',active:'Профиль подтверждён. Вход доступен',expired:'Срок доступа завершён',missing:'Бронь не найдена'};

export function createAccessUI({db,save,showModal,toast,navigate,refresh}) {
 const find=id=>db().bookings.find(b=>b.id===id);
 const state=b=>accessStatus(b,db().profile);
 function card(b){const s=state(b);if(['expired','missing'].includes(s))return '';return `<div class="booking-access"><p class="access-status ${['active','ready'].includes(s)?'approved':''}">${escape(labels[s])}</p><button class="button ${['active','ready'].includes(s)?'primary':''}" data-action="access-open" data-id="${b.id}">${['active','ready'].includes(s)?'QR-код для входа':s==='pending'?'Статус подтверждения':'Получить код доступа'}</button></div>`;}
 function ownerPanel(){const bookings=db().bookings.filter(b=>b.accessRequest).sort((a,b)=>b.accessRequest.requestedAt.localeCompare(a.accessRequest.requestedAt));return `<section class="access-owner-panel"><div class="access-section-head"><div><h2>Заявки на доступ</h2><p>Проверьте профиль арендатора и подтвердите допуск к его брони.</p></div><span class="demo-label">Демо-кабинет владельца</span></div><p class="mini-note">В прототипе обе роли доступны на одном устройстве. Одобрение относится только к выбранной брони.</p>${bookings.length?`<div class="access-requests">${bookings.map(b=>`<article class="access-request"><div><span class="status">${escape(labels[state(b)])}</span><h3>${escape(b.accessRequest.profile.name)}</h3><p>${escape(b.snapshot.title)} · ${date(b.start)} – ${date(b.end)}</p></div><button class="button" data-action="access-review" data-id="${b.id}">${state(b)==='pending'?'Проверить профиль':'Посмотреть заявку'}</button></article>`).join('')}</div>`:'<p class="access-empty">Заявок пока нет. Арендатор отправляет профиль из оплаченного бронирования.</p>'}</section>`;}
 function open(id){const b=find(id);if(!b)return toast('Бронь не найдена');const s=state(b),ready=['ready','active'].includes(s),canRequest=['new','changed','rejected','revoked'].includes(s);let qr='';
  if(ready){if(typeof window.qrcode!=='function')return toast('Модуль QR не загрузился. Обновите страницу.');const payload=accessPayload(b,db().profile,location.href);const code=window.qrcode(0,'M');code.addData(payload);code.make();const svg=code.createSvgTag({cellSize:5,margin:20,scalable:true});qr=`<div class="qr-pass"><div class="qr-image" role="img" aria-label="QR-код демонстрационного пропуска">${svg}</div><strong>${s==='active'?'Можно войти':'Пропуск подготовлен'}</strong><p>Действует с ${date(b.start)} до ${date(b.end)}</p><a class="button" download="SPACEGO-pass.svg" href="data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}">Скачать QR-код</a></div>`;}
  showModal(ready?'QR-код для входа':'Подтверждение доступа',`<div class="dialog-content"><h3>${escape(b.snapshot.title)}</h3><p class="access-address">${escape(b.snapshot.address)}</p><p class="access-status ${ready?'approved':''}">${escape(labels[s])}</p>${qr}${canRequest?`<div class="profile-snapshot"><h4>Профиль для владельца</h4><strong>${escape(db().profile?.name)}</strong><p>${escape(db().profile?.email)}</p><p>${escape(db().profile?.phone||'Телефон не указан')}</p></div><p class="mini-note">Владелец проверяет эти данные перед выдачей пропуска.</p>`:''}<p class="test-note">Демонстрационный доступ. QR проверяется только в этом браузере и не управляет физическим замком.</p><div class="dialog-actions">${s==='profile'?'<a class="button primary" href="#settings">Заполнить профиль</a>':s==='unpaid'?`<button class="button primary" data-action="pay" data-id="${id}">Тестовая оплата</button>`:canRequest?`<button class="button primary" data-action="access-request" data-id="${id}">Отправить профиль владельцу</button>`:ready?`<button class="button primary" data-action="access-check" data-id="${id}">Проверить пропуск</button>`:''}${['pending','ready','active'].includes(s)?'<button class="button" data-action="access-owner">Кабинет владельца · демо</button>':''}</div></div>`,true);
 }
 function review(id){const b=find(id);if(!b?.accessRequest)return toast('Заявка не найдена');const p=b.accessRequest.profile,s=state(b);showModal('Подтверждение профиля',`<div class="dialog-content"><span class="demo-label">Демо-кабинет владельца</span><div class="profile-snapshot"><h3>${escape(p.name)}</h3><p>${escape(p.email)}</p><p>${escape(p.phone||'Телефон не указан')}</p></div><h3>${escape(b.snapshot.title)}</h3><p>${date(b.start)} – ${date(b.end)}</p><p class="access-status">${escape(labels[s])}</p><p class="test-note">Подтверждается допуск к этой брони. Это не государственная проверка личности.</p><div class="dialog-actions">${s==='pending'?`<button class="button" data-action="access-reject" data-id="${id}">Отклонить</button><button class="button primary" data-action="access-approve" data-id="${id}">Подтвердить профиль и выдать QR</button>`:['ready','active'].includes(s)?`<button class="button danger" data-action="access-revoke" data-id="${id}">Отозвать доступ</button>`:''}</div></div>`,true);}
 function read(id,token){const result=validatePass(find(id),db().profile,token);showModal('Проверка пропуска',`<div class="dialog-content"><div class="pass-result ${result.valid?'approved':''}"><h3>${result.valid?'Пропуск действителен':'Вход недоступен'}</h3><p>${escape(result.reason)}</p></div><p class="test-note">Проверка локальная. Физический замок не подключён. На другом устройстве данные этой демо-брони недоступны.</p><div class="dialog-actions"><button class="button" data-action="access-open" data-id="${escape(id)}">К бронированию</button></div></div>`,true);}
 function handle(action,id){if(!action.startsWith('access-'))return false;const b=find(id);switch(action){
  case 'access-owner':navigate('owner');break;
  case 'access-open':open(id);break;
  case 'access-request':requestAccess(b,db().profile);save();refresh();open(id);toast('Заявка сохранена. Подтвердите её в демо-кабинете владельца.');break;
  case 'access-review':review(id);break;
  case 'access-approve':case 'access-reject':case 'access-revoke':{const decision={'access-approve':'approved','access-reject':'rejected','access-revoke':'revoked'}[action];decideAccess(b,db().profile,decision,decision==='approved'?crypto.randomUUID():null);save();refresh();review(id);toast(decision==='approved'?'Профиль подтверждён. QR доступен в бронировании.':decision==='rejected'?'Заявка отклонена':'Пропуск отозван');break;}
  case 'access-check':read(id,b?.accessRequest?.token);break;
 }return true;}
 return {card,ownerPanel,open,read,handle};
}
